import{_ as t,o as r,c as o,a4 as a}from"./chunks/framework.Dsbb2oA0.js";const m=JSON.parse('{"title":"CAD Drawing Operations · Entry Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/9.AIManual/1.EntryGuide.md","filePath":"en/docs/9.AIManual/1.EntryGuide.md"}'),n={name:"en/docs/9.AIManual/1.EntryGuide.md"};function d(i,e,s,c,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="cad-drawing-operations-·-entry-guide" tabindex="-1">CAD Drawing Operations · Entry Guide <a class="header-anchor" href="#cad-drawing-operations-·-entry-guide" aria-label="Permalink to &quot;CAD Drawing Operations · Entry Guide&quot;">​</a></h1><p>When a task involves CAD drawing operations, first determine which side (frontend or backend) it belongs to, then read and follow the corresponding guide.</p><h2 id="routing-rules" tabindex="-1">Routing Rules <a class="header-anchor" href="#routing-rules" aria-label="Permalink to &quot;Routing Rules&quot;">​</a></h2><table><thead><tr><th>User Intent</th><th>Side</th><th>Guide</th></tr></thead><tbody><tr><td>Preview, browse, edit, draw, annotate, measure, manage layers, or export drawings in a web page</td><td>Frontend (mxcad)</td><td><a href="./2.FrontendMxCadGuide.html">Frontend mxcad Guide</a></td></tr><tr><td>Server-side drawing file processing: format conversion, data extraction, parametric drawing generation, splitting/merging, batch export</td><td>Backend (MxServiceCode)</td><td><a href="./3.BackendMxServiceCodeGuide.html">Backend MxServiceCode Guide</a></td></tr><tr><td>SVG↔DWG conversion (svg to dwg / dwg to svg; mxcadassembly does not support SVG)</td><td>Backend (mxcad-svg-dwg-kit, new toolkit)</td><td><a href="./4.BackendReferenceDocs/4.SvgDwgKitGuide.html">SVG⇄DWG Conversion Kit Guide</a></td></tr><tr><td>Both sides involved (e.g. generate a DWG on the backend then preview it in a web page)</td><td>Backend generation first, then frontend preview</td><td>Read both guides in order</td></tr></tbody></table><p><strong>When the user has not made it clear whether this is a frontend or a backend task, you MUST ask first and only proceed after getting an answer:</strong></p><blockquote><p>Is this task about <strong>previewing/editing drawings in a web page</strong> (frontend mxcad), or about <strong>processing drawing files via the backend service</strong> (e.g. conversion, generation, data extraction)?</p></blockquote><p>Clues can help you guess but cannot replace asking: &quot;web page / browser / embedded website / mxcad / mxweb&quot; → frontend; &quot;server-side / Node / batch / generate drawing files / data extraction / API&quot; → backend.</p><h2 id="doc-links-program-download-urls" tabindex="-1">Doc Links &amp; Program Download URLs <a class="header-anchor" href="#doc-links-program-download-urls" aria-label="Permalink to &quot;Doc Links &amp; Program Download URLs&quot;">​</a></h2><h3 id="doc-links" tabindex="-1">Doc links <a class="header-anchor" href="#doc-links" aria-label="Permalink to &quot;Doc links&quot;">​</a></h3><table><thead><tr><th>Doc</th><th>Link</th></tr></thead><tbody><tr><td>Entry Guide (this file)</td><td><a href="./1.EntryGuide.html">link</a></td></tr><tr><td>Frontend mxcad Guide</td><td><a href="./2.FrontendMxCadGuide.html">link</a></td></tr><tr><td>Backend MxServiceCode Guide</td><td><a href="./3.BackendMxServiceCodeGuide.html">link</a></td></tr><tr><td>MxServiceCode Command Reference</td><td><a href="./4.BackendReferenceDocs/1.MxServiceCodeCommandReference.html">link</a></td></tr><tr><td>Mx2DNode Secondary Development API Reference</td><td><a href="./4.BackendReferenceDocs/2.Mx2DNodeSecondaryDevAPIReference.html">link</a></td></tr><tr><td>Deployment and Startup Notes</td><td><a href="./4.BackendReferenceDocs/3.DeploymentAndStartup.html">link</a></td></tr><tr><td>SVG⇄DWG Conversion Kit Guide</td><td><a href="./4.BackendReferenceDocs/4.SvgDwgKitGuide.html">link</a></td></tr></tbody></table><h3 id="program-download-urls" tabindex="-1">Program download URLs <a class="header-anchor" href="#program-download-urls" aria-label="Permalink to &quot;Program download URLs&quot;">​</a></h3><p>Two kinds of packages: <strong>standalone conversion program</strong> (MxConvert, mxcadassembly only) and <strong>backend service</strong> (MxServiceCode, contains BOTH the backend service and the conversion program — the complete superset). Both are trial versions (6 months), hosted on an external site (demo.mxdraw3d.com) — download directly by the absolute URLs below. The Linux packages are built for Ubuntu 20.04 (<code>Ubuntu20</code>), x86_64, and work on compatible newer environments (e.g. Ubuntu 22.04); on ARM machines (<code>uname -m</code> = <code>aarch64</code>) or older systems, stop and confirm with the user first.</p><table><thead><tr><th>Program</th><th>Platform</th><th>Download URL</th></tr></thead><tbody><tr><td>Standalone conversion program MxConvert (trial version)</td><td>Windows</td><td><a href="https://demo.mxdraw3d.com/download/MxConvert_TryVersion.zip" target="_blank" rel="noreferrer">MxConvert_TryVersion.zip</a></td></tr><tr><td>Standalone conversion program MxConvert (trial version)</td><td>Linux (Ubuntu 20.04 x86_64)</td><td><a href="https://demo.mxdraw3d.com/download/MxConvert_Ubuntu20_TryVersion.zip" target="_blank" rel="noreferrer">MxConvert_Ubuntu20_TryVersion.zip</a></td></tr><tr><td>Backend service MxServiceCode (includes conversion program mxcadassembly, trial version)</td><td>Windows</td><td><a href="https://demo.mxdraw3d.com/download/MxServiceCode_TryVersion.zip" target="_blank" rel="noreferrer">MxServiceCode_TryVersion.zip</a></td></tr><tr><td>Backend service MxServiceCode (includes conversion program mxcadassembly, trial version)</td><td>Linux (Ubuntu 20.04 x86_64)</td><td><a href="https://demo.mxdraw3d.com/download/MxServiceCode_Ubuntu20_TryVersion.zip" target="_blank" rel="noreferrer">MxServiceCode_Ubuntu20_TryVersion.zip</a></td></tr><tr><td>SVG⇄DWG conversion kit mxcad-svg-dwg-kit (pure JS; the launcher provisions node &amp; the backend service automatically — auto-downloads the service on first run; ships full sources + build tools)</td><td>All platforms (pure JS)</td><td><a href="https://demo.mxdraw3d.com/download/mxcad-svg-dwg-kit.zip" target="_blank" rel="noreferrer">mxcad-svg-dwg-kit.zip</a> (if unreachable, ask the user)</td></tr></tbody></table><p><strong>Fixed temp path (download once, reuse across sessions)</strong>:</p><ul><li>Windows: <code>%TEMP%\\MxCAD\\</code> (<code>%TEMP%</code> is the user&#39;s Temp directory environment variable; use it as-is in commands, no manual expansion needed)</li><li>Linux: <code>/tmp/MxCAD/</code></li></ul><p><strong>Program check &amp; acquisition steps</strong> (run after receiving a task):</p><p><strong>Step 1 — Determine what the task needs</strong>: only the conversion program (format conversion / PDF / image, i.e. <code>mxcadassembly</code> calls), or the backend service (command calls / secondary development).</p><p><strong>Step 2 — Inspect what is already in the fixed temp path</strong> and handle per the table below:</p><table><thead><tr><th>Current state of temp dir</th><th>Task needs only the conversion program</th><th>Task needs the backend service</th></tr></thead><tbody><tr><td>Nothing there</td><td>Download the <strong>standalone conversion program</strong> (MxConvert) zip for the platform and extract it to the temp path</td><td>Download the <strong>backend service</strong> (MxServiceCode) zip for the platform (contains the conversion program) and extract it to the temp path</td></tr><tr><td>Only the conversion program (extracted from the standalone package, may not be under <code>MxCAD\\Release\\</code>)</td><td>Run the trial-expiry verification directly; if it passes, use it</td><td><strong>Clear the temp path, then download and extract the backend service zip</strong></td></tr><tr><td>Backend service present (extracted; conversion program in <code>MxCAD\\Release\\</code> / <code>Linux\\MxCAD\\</code>)</td><td>Run trial-expiry verification + package integrity check; use if both pass; <strong>if incomplete, clear and re-download the standalone conversion program zip</strong></td><td>Verify the project dir <code>MxServiceCode\\MxServiceCode</code> is complete; use if complete; <strong>if incomplete, clear and re-download the backend service zip</strong></td></tr></tbody></table><blockquote><p>Note: each package has a FIXED directory structure: both zips extract to a single top-level directory named after the zip (<code>MxConvert_TryVersion\\</code> / <code>MxServiceCode_TryVersion\\</code>). In the standalone conversion program package the program files (mxcadassembly.exe, fonts, etc.) sit directly in that top-level dir; the backend service package contains two subdirectories inside it — <code>MxServiceCode\\</code> + <code>MxCAD\\Release\\</code> (Windows) / <code>MxServiceCode\\</code> + <code>Linux\\MxCAD\\</code> (Linux). Therefore <strong>the temp path MUST be cleared before any re-download</strong> (the backend package is a complete superset containing both the backend and the conversion program, so clearing and re-extracting loses nothing). After the system cleans the temp dir, just re-download. Do NOT scan other directories on the user&#39;s machine.</p></blockquote>',20)])])}const g=t(n,[["render",d]]);export{m as __pageData,g as default};
